import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-cash-refund',
    title: 'customersView.customerDetails.payDebt',
    messages: ['customersView.settleDebtDialog.altMessage'],
    extraValuesMessages: [
      formatNumberFromDbToCurrency(
        state.sale.receivable.amount - state.sale.receivable.settled
      ),
    ],
    titleBackground: '#white',
    titleColor: 'textPrimary',
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    height: 225,
    maxWidth: 500,
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: state.routeName,
        screen: 'SettleCreditSale',
        name: 'Cancel',
      })
      methods.closeDialog()
    },
    onClickAccept: () => methods.settleDebt(),
  },
})

export default setConfig
