<template>
  <DialogCard :config="dialogConfig.dialogData" />
</template>

<script>
import { mapActions, mapState } from 'vuex'

import { testMode } from '@/config/env'
import CUSTOMERS_DB_API_EVENTS from '@/config/events/databaseAPI/customersEvents'

import { formatNumberToDb, formatNumberFromDb } from '@/tools/numbersFormat'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import appActions from '@/store/app/actions.types'
import customersActions from '@/store/customers/actions.types'
import customersViewActions from '@/store/customersView/actions.types'
import usersViewActions from '@/store/usersView/actions.types'

import setConfig from '@/components/CustomersView/CustomerDetail/CreditSalesTab/SettleCreditSaleDialog/config'
import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'SettleCreditSaleDialog',
  components: { DialogCard },
  props: {
    customer: {
      type: Object,
      default: null,
    },
  },
  data() {
    return {
      settlingDebt: false,
    }
  },
  computed: {
    ...mapState('customersView', [
      'settleCreditSaleDialog',
      'customerDetailDialog',
    ]),
    ...mapState('usersView', ['selectedUser', 'estimatedCash']),
    dialogConfig() {
      return setConfig(
        {
          isOpen: this.settleCreditSaleDialog.isOpen,
          sale: this.settleCreditSaleDialog.sale,
          routeName: this.$route.name,
        },
        {
          closeDialog: this.closeDialog,
          settleDebt: this.settleDebt,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.addPendingSyncOperation]),
    ...mapActions('customers', [customersActions.settleCreditSale]),
    ...mapActions('customersView', [
      customersViewActions.setSettleCreditSaleDialogStatus,
    ]),
    ...mapActions('usersView', [usersViewActions.setUserEstimatedCash]),
    getEstimatedCash() {
      const stateEstimatedCash =
        this.estimatedCash === null || this.estimatedCash === undefined
          ? 0
          : this.estimatedCash
      return formatNumberToDb(stateEstimatedCash)
    },
    closeDialog() {
      this[customersViewActions.setSettleCreditSaleDialogStatus]({
        isOpen: false,
        sale: null,
      })
    },
    settleDebt() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'SettleCreditSale',
        name: 'Settle credit sale',
      })
      if (this.settlingDebt === true) return
      this.settlingDebt = true
      rendererEventsService.send(CUSTOMERS_DB_API_EVENTS.channel, {
        event: CUSTOMERS_DB_API_EVENTS.events.settleCreditSale.name,
        data: {
          sale: this.settleCreditSaleDialog.sale,
          customer:
            this.customer === null
              ? this.customerDetailDialog.customerSelected
              : this.customer,
          user: this.selectedUser.id,
          estimatedCash: this.getEstimatedCash(),
        },
      })
    },
    onSaleSettled(data) {
      this.$track({
        type: 'system',
        action: 'settle_credit_sale',
        category: this.$route.name,
        screen: 'SettleCreditSale',
        name: 'Close dialog',
      })
      this[appActions.addPendingSyncOperation]()
      this[customersActions.settleCreditSale](data.customer)
      this[usersViewActions.setUserEstimatedCash](
        formatNumberFromDb(data.estimatedCash)
      )
      this.$root.$emit('updateCustomers')
      notificationsService.showSuccess(
        'customersView.settleDebtDialog.idividualDebtSettled',
        this.$vuetify.lang,
        { timeout: 8000 }
      )
      this.closeDialog()
      this.settlingDebt = false
      this.$root.$emit('debtSettled')
    },
    onSaleSettledError() {
      this.$track({
        type: 'system',
        action: 'error',
        category: this.$route.name,
        screen: 'SettleCreditSale',
        name: 'Error settling credit sale',
      })
      notificationsService.showError(
        'customersView.settleDebtDialog.errorSettlingDebt',
        this.$vuetify.lang,
        { timeout: 8000 }
      )
      this.settlingDebt = false
    },
  },
  mounted() {
    if (testMode) return
    rendererEventsService.subscribe(
      CUSTOMERS_DB_API_EVENTS.replyChannel,
      (event, payload) => {
        const settleCreditSaleReplies =
          CUSTOMERS_DB_API_EVENTS.events.settleCreditSale.replies
        const replies = {
          [settleCreditSaleReplies.success]: () =>
            this.onSaleSettled(payload.data),
          [settleCreditSaleReplies.error]: () =>
            this.onSaleSettledError(payload.data),
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(
      CUSTOMERS_DB_API_EVENTS.replyChannel
    )
  },
}
</script>
