<template>
  <v-dialog
    v-model="operationDetailDialog.isOpen"
    max-width="650"
    :overlay-opacity="0.15"
    content-class="default-dialog"
    @click:outside="onClickOutside"
  >
    <v-card
      flat
      class="view-section"
      id="operation-detail-card"
      :class="{ collapsed: operationDetailDialog.isOpen }"
      :height="dialogHeight"
      color="cardBackgroundPrimary"
    >
      <Header />
      <ExtraDetails />
      <Footer />
    </v-card>
  </v-dialog>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { idOperations } from '@/config/cashOperationsVariables'

import operationsViewActions from '@/store/operationsView/actions.types'

import Header from '@/components/OperationsView/OperationDetail/Header'
import ExtraDetails from '@/components/OperationsView/OperationDetail/ExtraDetails'
import Footer from '@/components/OperationsView/OperationDetail/Footer'

export default {
  name: 'OperationDetail',
  components: { Header, ExtraDetails, Footer },
  computed: {
    ...mapState('operationsView', ['operationDetailDialog']),
    dialogHeight() {
      let height
      switch (this.operationDetailDialog.operationSelected.operationType) {
        case idOperations.ID_OPERATION_EXPENSE:
        case idOperations.ID_OPERATION_ADDCASH:
        case idOperations.ID_OPERATION_TAKECASH:
          height = 420
          break
        default:
          height = 700
          break
      }
      return height
    },
  },
  methods: {
    ...mapActions('operationsView', [
      operationsViewActions.setOperationDetailDialogStatus,
    ]),
    onClickOutside() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Operations',
        screen: 'OperationDetails',
        name: 'Close operation details',
      })
      this[operationsViewActions.setOperationDetailDialogStatus]({
        isOpen: false,
      })
    },
  },
  beforeDestroy() {
    if (this.operationDetailDialog.isOpen) this.onClickOutside()
  },
}
</script>
