<template>
  <DialogCard :config="dialogConfig.dialogData" />
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { testMode } from '@/config/env'
import CASH_OPERATIONS_DB_API_EVENTS from '@/config/events/databaseAPI/cashOperationsEvents'

import { formatNumberToDb, formatNumberFromDb } from '@/tools/numbersFormat'

import notificationsService from '@/services/renderer/notifications'
import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'
import productsActions from '@/store/products/actions.types'
import operationsViewActions from '@/store/operationsView/actions.types'
import usersViewActions from '@/store/usersView/actions.types'
import loyaltyProgramActions from '@/store/loyaltyProgram/actions.types'
import customersActions from '@/store/customers/actions.types'

import setDialogConfig from '@/components/OperationsView/OperationDetail/Footer/DeleteOperationDialog/config'
import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'DeleteOperationDialog',
  components: { DialogCard },
  data() {
    return {
      deletingOperation: false,
    }
  },
  computed: {
    ...mapState('operationsView', {
      operationSelected: state => state.operationDetailDialog.operationSelected,
      deleteOperationDialog: state => state.deleteOperationDialog,
    }),
    ...mapState('usersView', ['selectedUser', 'estimatedCash']),
    ...mapState('products', { products: state => state.data.products }),
    dialogConfig() {
      return setDialogConfig(
        {
          opened: this.deleteOperationDialog.isOpen,
          operation: this.operationSelected,
          routeName: this.$route.name,
        },
        {
          closeDialog: this.closeDialog,
          undoOperation: this.deleteOperation,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.addPendingSyncOperation]),
    ...mapActions('products', [productsActions.editProductField]),
    ...mapActions('operationsView', [
      operationsViewActions.setDeleteOperationDialogStatus,
    ]),
    ...mapActions('usersView', [usersViewActions.setUserEstimatedCash]),
    ...mapActions('loyaltyProgram', [
      loyaltyProgramActions.updateEnrolledCustomerByProperties,
      loyaltyProgramActions.updateLastSaleDate,
    ]),
    ...mapActions('customers', [customersActions.settleCreditSale]),
    getEstimatedCash() {
      const stateEstimatedCash =
        this.estimatedCash === null || this.estimatedCash === undefined
          ? 0
          : this.estimatedCash
      return formatNumberToDb(stateEstimatedCash)
    },
    closeDialog() {
      this[operationsViewActions.setDeleteOperationDialogStatus](false)
    },
    deleteOperation() {
      if (this.deletingOperation === true) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'DeleteOperationDialog',
        name: 'Confirm',
      })
      this.deletingOperation = true
      rendererEventsService.send(CASH_OPERATIONS_DB_API_EVENTS.channel, {
        event: CASH_OPERATIONS_DB_API_EVENTS.events.undoOperation.name,
        data: {
          operation: this.operationSelected,
          user: this.selectedUser,
          products: this.products,
          estimatedCash: this.getEstimatedCash(),
        },
      })
    },
    cashOperationListener(event, payload) {
      const events = CASH_OPERATIONS_DB_API_EVENTS.events
      const replies = {
        [events.undoOperation.replies.success]: () =>
          this.onOperationUndone(payload.data),
        [events.undoOperation.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: this.$route.name,
            screen: 'DeleteOperationDialog',
            name: 'Error undoing operation',
          })
          notificationsService.showError(
            payload.data.errorMsg,
            this.$vuetify.lang
          )
          this.deletingOperation = false
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    onOperationUndone(data) {
      this.$track({
        type: 'system',
        action: 'undo_operation',
        category: this.$route.name,
        screen: 'DeleteOperationDialog',
        name: 'Close dialog',
      })
      this[appActions.addPendingSyncOperation]()
      data.products.forEach(product => {
        this[appActions.addPendingSyncOperation]()
        this[productsActions.editProductField](product)
      })
      data.returnProducts.forEach(returnProduct => {
        this[appActions.addPendingSyncOperation]()
        this[productsActions.editProductField](returnProduct)
      })
      this[usersViewActions.setUserEstimatedCash](
        formatNumberFromDb(data.estimatedCash)
      )
      if (data.customer) {
        this[customersActions.settleCreditSale](data.customer)
      }
      this.$root.$emit('updateCustomers')
      if (data.enrolledCustomer) {
        this[loyaltyProgramActions.updateEnrolledCustomerByProperties]({
          ...data.enrolledCustomer,
          status: Number(data.enrolledCustomer.status),
        })
        this[loyaltyProgramActions.updateLastSaleDate]({
          lastSaleDate: data.lastSaleDate,
          customerId: data.enrolledCustomer.customerId,
        })
      }
      this.closeDialog()
      this.$root.$emit('operationDeleted')
      notificationsService.showSuccess(
        'notification.operations.operationUndone',
        this.$vuetify.lang
      )
      this.deletingOperation = false
    },
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      CASH_OPERATIONS_DB_API_EVENTS.replyChannel,
      this.cashOperationListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      CASH_OPERATIONS_DB_API_EVENTS.replyChannel,
      this.cashOperationListener
    )
  },
}
</script>
