import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-cash-refund',
    title: 'vendorsView.dialogs.settleDebtDialog.payDebt',
    messages: ['vendorsView.dialogs.settleDebtDialog.altMessage'],
    persistent: true,
    extraValuesMessages: [
      formatNumberFromDbToCurrency(
        state.purchase.payable.amount - state.purchase.payable.settled
      ),
    ],
    titleBackground: '#white',
    titleColor: 'textPrimary',
    height: 225,
    maxWidth: 500,
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: state.routeName,
        screen: 'SettleCreditPurchaseDialog',
        name: 'Cancel',
      })
      methods.closeDialog()
    },
  },
  multipleButtons: [
    {
      ref: 'cancelButton',
      color: 'accent',
      onClick: () => {
        methods.track({
          type: 'interaction',
          action: 'click',
          category: state.routeName,
          screen: 'SettleCreditPurchaseDialog',
          name: 'Cancel',
        })
        methods.closeDialog()
      },
      text: 'shared.cancel',
    },
    {
      tooltip: {
        text: 'vendorsView.dialogs.settleDebtDialog.payExternalCashRegister',
      },
      ref: 'externalCashRegister',
      color: 'primary',
      onClick: () => methods.showInfoDialog(true),
      text: 'vendorsView.dialogs.settleDebtDialog.externalCashRegister',
    },
    {
      tooltip: {
        text: 'vendorsView.dialogs.settleDebtDialog.payMainCashRegister',
      },
      ref: 'mainCashRegister',
      color: 'primary',
      onClick: () => methods.showInfoDialog(),
      text: 'vendorsView.dialogs.settleDebtDialog.mainCashRegister',
    },
  ],
})

export default setConfig
