<template>
  <v-hover v-model="isHover">
    <div
      class="combo-promotion-ticket"
      :class="{ 'pl-6 pr-2 pt-3': !isOperationSection }"
    >
      <ActionsButtons :is-hover="isHover" :actions="actions" />
      <v-card
        flat
        :color="cardColor"
        class="py-2 px-4 combo-promotion-ticket__card"
      >
        <div class="combo-promotion-ticket__quantity">
          <ProductQuantity
            :product="promotion"
            text="customPromotionsView.inSale.ticket.offer"
          />
        </div>
        <div class="combo-promotion-ticket__info pl-1">
          <div class="d-flex flex-column">
            <p class="text-h6 error--text text-ellipsis mb-0">
              <v-icon color="error">mdi-sale</v-icon>
              {{
                getTranslatedText('customPromotionsView.inSale.ticket.combo')
              }}
            </p>
            <div>
              <p
                v-for="key in keysProducts"
                :key="`${key}Name`"
                class="combo-products-name productProductNameTicket--text text--lighten-1 font-weight-medium text-ellipsis mb-0"
              >
                {{ promotion.promotions[key].name }}
                {{ promotion.promotions[key].alternativeName }}
              </p>
              <div class="d-flex combo-unit-price">
                <v-icon :color="iconColor" class="pr-1">
                  $currencyUsdCircle
                </v-icon>
                <p class="text-h6 mb-0" :class="priceColor">
                  {{ formatNumberFromDbToCurrency(promotion.promotions.total) }}
                </p>
              </div>
            </div>
          </div>
        </div>
        <div class="combo-promotion-ticket__total">
          <div class="d-flex flex-column align-end">
            <p
              class="text-h5 productProductNameTicket--text text--lighten-1 font-weight-bold"
            >
              {{ formatNumberFromDbToCurrency(totalCombo) }}
            </p>
          </div>
        </div>
      </v-card>
    </div>
  </v-hover>
</template>

<script>
import { mapActions } from 'vuex'

import { getTranslatedText } from '@/tools/data'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'
import { comboPromotion } from '@/tools/customPromotions'

import salesActions from '@/store/sales/actions.types'

import ActionsButtons from '@/components/shared/Ticket/Product/ActionsButtons'
import ProductQuantity from '@/components/shared/Ticket/Product/ProductQuantity'

export default {
  name: 'ComboPromotion',
  components: { ProductQuantity, ActionsButtons },
  props: {
    ticketIndex: {
      type: Number,
      required: true,
    },
    promotion: {
      type: Object,
      required: true,
    },
    hideDeleteBtn: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      isHover: false,
    }
  },
  computed: {
    actions() {
      return {
        add: {
          on: { click: () => this.changeQuantity(1) },
          show: !this.isOperationSection,
        },
        subtract: {
          on: { click: () => this.changeQuantity(-1) },
          show: !this.isOperationSection,
        },
        delete: {
          on: { click: this.deleteComboPromotion },
          show: !this.hideDeleteBtn,
        },
      }
    },
    totalCombo() {
      return this.promotion.promotions.total * this.promotion.quantity
    },
    keysProducts() {
      return comboPromotion.getProductsKey()
    },
    isOperationSection() {
      return (
        this.$route.name === 'Operations' || this.$route.name === 'Customers'
      )
    },
    cardColor() {
      return this.isOperationSection
        ? 'cardBackgroundSecondary'
        : 'cardBackgroundPrimary'
    },
    iconColor() {
      return this.isOperationSection
        ? 'productProductNameTicket lighten-2'
        : 'primary lighten-1'
    },
    priceColor() {
      return this.isOperationSection
        ? 'productProductNameTicket--text text--lighten-2'
        : 'primary--text text--lighten-1'
    },
  },
  methods: {
    ...mapActions('sales', [
      salesActions.updateSalePromotionsQuantity,
      salesActions.deleteSalePromotions,
    ]),
    formatNumberFromDbToCurrency,
    getTranslatedText,
    changeQuantity(quantity) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Sales',
        screen: 'TicketCombo',
        name: `${quantity > 0 ? 'Add' : 'Subtract'} combo quantity`,
      })
      this[salesActions.updateSalePromotionsQuantity]({
        ticketIndex: this.ticketIndex,
        promotion: this.promotion,
        quantity,
      })
    },
    deleteComboPromotion() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Sales',
        screen: 'TicketCombo',
        name: 'Remove combo',
      })
      if (this.isOperationSection) {
        this.$emit('deleteComboFromSaleOp')
        return
      }
      this[salesActions.deleteSalePromotions]({
        ticketIndex: this.ticketIndex,
        promotion: this.promotion,
      })
    },
  },
}
</script>

<style scoped lang="scss">
.combo-promotion-ticket {
  position: relative;
  &__card {
    display: flex;
    gap: 12px;
    border-radius: 10px;
    &:focus:before {
      opacity: 0;
    }
  }
  &__quantity {
    width: 60px;
  }
  &__info {
    flex: 1;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  &__total {
    white-space: nowrap;
    text-align: end;
  }
}
.text-ellipsis {
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
  max-width: 95%;
  box-sizing: border-box;
  flex-shrink: 1;
}
</style>
