<template>
  <div>
    <Product
      price-key="price"
      :price-without-promotion-key="priceWithoutPromotionKey"
      :product="item"
      :actions="cardActions"
      :pay-option="operationSelected.operationType"
    />
    <DeleteProductDialog v-if="isDialogOpened" />
  </div>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import CASH_OPERATIONS_EVENTS from '@/config/events/databaseAPI/cashOperationsEvents'
import { idOperations } from '@/config/cashOperationsVariables'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import operationsViewActions from '@/store/operationsView/actions.types'

import DeleteProductDialog from '@/components/OperationsView/OperationDetail/ExtraDetails/DetailItem/DeleteProductDialog'
import Product from '@/components/shared/Ticket/Product'

export default {
  name: 'OperationDetailExtraDetailsItem',
  components: { Product, DeleteProductDialog },
  props: {
    item: {
      type: Object,
      required: true,
    },
  },
  computed: {
    ...mapState('operationsView', {
      operationSelected: state => state.operationDetailDialog.operationSelected,
      deleteOperationDialog: state => state.deleteOperationDialog,
      deleteProductDialog: state => state.deleteProductDialog,
    }),
    ...mapState('usersView', {
      user: state => state.selectedUser,
    }),
    isDialogOpened() {
      return (
        this.deleteProductDialog.isOpen &&
        this.deleteProductDialog.productSelected.id == this.item.id
      )
    },
    priceWithoutPromotionKey() {
      switch (this.operationSelected.operationType) {
        case idOperations.ID_OPERATION_CASH_SALE:
        case idOperations.ID_OPERATION_CREDIT_SALE:
        case idOperations.ID_OPERATION_EXTERNAL_PAYMENT_SALE:
        case idOperations.ID_OPERATION_OWNER_SALE:
          return 'priceWithoutPromotion'
        case idOperations.ID_OPERATION_CASH_PURCHASE:
        case idOperations.ID_OPERATION_CREDIT_PURCHASE:
          return 'costWithoutPromotion'
        default:
          return 'price'
      }
    },
    cardActions() {
      return {
        delete: {
          on: { click: () => this.openDeleteDialog(this.operationSelected) },
          show:
            [
              idOperations.ID_OPERATION_CREDIT_SALE,
              idOperations.ID_OPERATION_CASH_SALE,
            ].includes(this.operationSelected.operationType) &&
            this.operationSelected.details.promotion <= 0 &&
            this.user.salesPurchasesReturnPermission === 0 &&
            !this.productIsInCombo,
        },
      }
    },
    productIsInCombo() {
      return this.operationSelected.details.promotions.some(promo => {
        return [
          promo.promotions.firstProductId,
          promo.promotions.secondProductId,
        ].includes(this.item.productId)
      })
    },
  },
  methods: {
    ...mapActions('operationsView', [
      operationsViewActions.setDeleteOperationDialogStatus,
      operationsViewActions.setDeleteProductDialogStatus,
    ]),
    openDeleteDialog(operationSelected) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'OperationItemDetails',
        name: 'Remove product',
      })
      rendererEventsService.send(CASH_OPERATIONS_EVENTS.channel, {
        event: CASH_OPERATIONS_EVENTS.events.operationCanBeUndone.name,
        data: { operationSelected, item: this.item },
      })
    },
    cashOperationsListener(event, payload) {
      const replies = {
        [`${CASH_OPERATIONS_EVENTS.events.operationCanBeUndone.replies.success}-${this.item.id}`]: () => {
          if (payload.data.canBeUndone === false) {
            this.$track({
              type: 'system',
              action: 'can_be_undone',
              category: this.$route.name,
              screen: 'OperationItemDetails',
              name: 'Product cannot be deleted',
            })
            notificationsService.showError(
              'notification.operations.productCantBeUndone',
              this.$vuetify.lang
            )
            return
          }
          if (
            this.operationSelected.details.items.length +
              this.operationSelected.details.promotions.length >
            1
          ) {
            this[operationsViewActions.setDeleteProductDialogStatus]({
              isOpen: true,
              productSelected: this.item,
            })
            this.$track({
              type: 'system',
              action: 'can_be_undone',
              category: this.$route.name,
              screen: 'OperationItemDetails',
              name: 'Show confirm delete product',
            })
            return
          }
          this[operationsViewActions.setDeleteOperationDialogStatus](true)
          this.$track({
            type: 'system',
            action: 'can_be_undone',
            category: this.$route.name,
            screen: 'OperationItemDetails',
            name: 'Show confirm delete operation',
          })
        },
        [`${CASH_OPERATIONS_EVENTS.events.operationCanBeUndone.replies.error}-${this.item.id}`]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: this.$route.name,
            screen: 'OperationItemDetails',
            name: 'Error checking if product can be deleted',
          })
          notificationsService.showError(
            'notification.operations.productCantBeUndone',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    rendererEventsService.subscribe(
      CASH_OPERATIONS_EVENTS.replyChannel,
      this.cashOperationsListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      CASH_OPERATIONS_EVENTS.replyChannel,
      this.cashOperationsListener
    )
  },
}
</script>
