<template>
  <v-card-text flat color="cardBackgroundPrimary" class="items-scroll">
    <div class="py-1 d-flex justify-space-between align-center widget-title">
      <div class="d-flex">
        <v-icon>
          {{ operationSelected.details.extraDetailIcon }}
        </v-icon>
        <FormattedText
          intl
          type="text-body-1"
          :value="operationSelected.details.extraDetailTitle"
          class="pl-2 pt-1"
          className="font-weight-bold"
        />
      </div>
      <v-btn
        v-if="showReceipt"
        small
        text
        @click="printCopyTicket"
        v-track:click="{
          category: $route.name,
          screen: 'OperationDetails',
          name: 'Print ticket',
        }"
      >
        <v-icon>mdi-printer</v-icon>
        <FormattedText
          intl
          type="text-body-2"
          value="operationsView.listView.printTicket"
          class="pl-2"
          className="font-weight-bold"
        />
      </v-btn>
    </div>
    <div
      v-if="showReceipt"
      class="scroll-height"
      :style="{ height: heightScroll }"
    >
      <div class="p-6" id="ticket-to-print" v-show="false">
        <TicketToPrint
          :products="products"
          :returnProducts="returnProducts"
          :combos="saleCombos"
          isCopy
          :operationType="operationSelected.operationType"
          :details="details"
          :operationDate="operationSelected.date"
          :ticketPromotion="ticketPromotion"
        />
      </div>
      <ScrollContainer
        v-if="
          operationSelected.details.items ||
            operationSelected.details.returnItems
        "
        height="380px"
        max-height="380px"
        :scroll-active-style="{
          'margin-right': '-20px',
          'padding-right': '4px',
        }"
      >
        <DetailItem
          v-for="item in products"
          :key="`item${item.id}`"
          :item="item"
          class="pt-2 detail-item"
        />
        <DetailReturnItem
          v-for="item in returnProducts"
          :key="`returnProduct${item.id}`"
          :item="item"
          class="pt-2 detail-item"
        />
        <DetailCombo
          v-for="combo in saleCombos"
          :key="`combo${combo.id}`"
          :combo="combo"
          :operation="operationSelected"
          class="pt-2 detail-item"
        />
      </ScrollContainer>
      <div v-else>
        <DetailDebt :debt="operationSelected.details" class="mt-2" />
      </div>
    </div>
    <div
      v-else
      class="d-flex flex-column justify-center align-center top-negative"
    >
      <div class="align-start">
        <FormattedText
          v-if="operationSelected.extraInfo"
          :value="operationSelected.extraInfo"
          className="font-weight-bold"
          class="mb-2"
        />
        <FormattedText
          v-else
          intl
          value="operationsView.detail.totalAmount"
          className="font-weight-bold"
          type="text-h5"
        />
      </div>
      <div class="total-container">
        <FormattedText
          type="text-h4"
          className="font-weight-bold"
          class="text-center"
          :value="formatNumberFromDbToCurrency(operationSelected.amount)"
        />
      </div>
    </div>
  </v-card-text>
</template>

<script>
import { mapGetters, mapState } from 'vuex'

import PRINTER_EVENTS from '@/config/events/printer'
import { idOperations } from '@/config/cashOperationsVariables'
import paymentMethods from '@/config/paymentMethods'

import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'
import { discountTypes, getPercentFromAmount } from '@/tools/promotions'

import rendererEventsService from '@/services/renderer/rendererEvents'

import DetailItem from '@/components/OperationsView/OperationDetail/ExtraDetails/DetailItem'
import DetailDebt from '@/components/OperationsView/OperationDetail/ExtraDetails/DetailDebt'
import DetailReturnItem from '@/components/OperationsView/OperationDetail/ExtraDetails/DetailReturnItem'
import TicketToPrint from '@/components/TicketToPrint'
import FormattedText from '@/components/shared/FormattedText'
import ScrollContainer from '@/components/shared/ScrollContainer'
import DetailCombo from '@/components/OperationsView/OperationDetail/ExtraDetails/DetailCombo'
import tools from '@/components/OperationsView/OperationDetail/ExtraDetails/extraDetails.tools'

export default {
  name: 'OperationDetailExtraDetails',
  components: {
    DetailCombo,
    ScrollContainer,
    DetailItem,
    DetailDebt,
    DetailReturnItem,
    FormattedText,
    TicketToPrint,
  },
  data() {
    return {
      heightScroll: '380px',
    }
  },
  computed: {
    ...mapState('operationsView', {
      operationSelected: state => state.operationDetailDialog.operationSelected,
    }),
    ...mapState('app', ['addMarginTicket']),
    ...mapGetters({
      storeInventoryProducts: 'products/getFilteredData',
    }),
    itemsToShow() {
      return this.operationSelected.details.items.filter(
        item => !(item.product_id === -1 && item.name === 'commission')
      )
    },
    showReceipt() {
      return ![
        idOperations.ID_OPERATION_EXPENSE,
        idOperations.ID_OPERATION_ADDCASH,
        idOperations.ID_OPERATION_TAKECASH,
      ].includes(this.operationSelected.operationType)
    },
    details() {
      return this.operationSelected.operationType ===
        idOperations.ID_OPERATION_CREDIT_SALE
        ? {
            ...this.operationSelected.details,
            payOption: paymentMethods.creditKey,
          }
        : this.operationSelected.details
    },
    products() {
      return tools.getProductsByOperationType.call(this)
    },
    returnProducts() {
      return tools.getReturnProducts.call(this)
    },
    saleCombos() {
      return tools.getSaleCombos.call(this)
    },
    getIconTitle() {
      return 'mdi-card-account-details-outline'
    },
    ticketPromotion() {
      if (
        !this.operationSelected.details.promotion ||
        this.operationSelected.details.promotion <= 0
      ) {
        return null
      }
      return {
        promotion: this.getPromotion(
          this.operationSelected.amount,
          this.operationSelected.details.promotion,
          this.operationSelected.details.promotion_type
        ),
        promotionType: this.operationSelected.details.promotion_type,
      }
    },
  },
  methods: {
    formatNumberFromDbToCurrency,
    printCopyTicket() {
      rendererEventsService.send(PRINTER_EVENTS.channel, {
        event: PRINTER_EVENTS.events.printSale.name,
        data: {
          ticketToPrint: document.getElementById('ticket-to-print').innerHTML,
          addMarginTicket: this.addMarginTicket,
        },
      })
    },
    getPromotion(totalAmount, promotion, promotionType) {
      if (discountTypes.isDiscountPerAmount(promotionType)) return promotion
      const amountWithoutDiscount = totalAmount + promotion
      return getPercentFromAmount(promotion, amountWithoutDiscount)
    },
  },
  mounted() {
    this.$nextTick(() => {
      const dialog = document.getElementById('operation-detail-card')
      const dialogHeight = dialog.offsetHeight
      const dialogHeaderHeight = dialog.getElementsByClassName(
        'v-card__title'
      )[0].offsetHeight
      const dialogFooterHeight = dialog.getElementsByClassName(
        'v-card__actions'
      )[0].offsetHeight
      this.heightScroll = `${dialogHeight -
        (dialogHeaderHeight + dialogFooterHeight) -
        85}px`
    })
  },
}
</script>

<style lang="scss" scoped>
.items-scroll {
  border-radius: 8px;
}
.total-container {
  background-color: var(--v-cardBackgroundSecondary-base);
  border-radius: 16px;
  height: 100px;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 400px;
}
.top-negative {
  margin-top: -15px;
}
.detail-item {
  :deep(> div.px-6) {
    padding: 0 !important;
  }
}
</style>
