import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-alert-circle',
    title: 'operationsView.deleteComboDialog.title',
    titleBackground: '',
    titleColor: 'textPrimary',
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    messages: ['operationsView.deleteComboDialog.message'],
    extraValuesMessages: [
      state.combo.promotions.firstProduct.name,
      state.combo.promotions.secondProduct.name,
      formatNumberFromDbToCurrency(state.combo.promotions.total),
    ],
    height: 225,
    maxWidth: 500,
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: state.routeName,
        screen: 'DeleteComboDialog',
        name: 'Cancel',
      })
      methods.closeDialog()
    },
    onClickAccept: () => methods.deleteCombo(),
  },
})

export default setConfig
