<template>
  <v-card-title class="large-icon-title">
    <div>
      <FormattedText
        type="text-h5"
        className="operation-name font-weight-bold mb-0"
        class="operation-name-padding"
        :value="getOperationType"
      />
      <FormattedText
        v-if="getExtraInfoOperationType"
        className="operation-name font-weight-medium"
        type="text-subtitle-1"
        :value="getExtraInfoOperationType"
      />
      <FormattedText className="operation-name" type="text-subtitle-1">
        {{
          `${getTranslatedText(
            'operationsView.detail.doneOn'
          )} ${getDateWithFormat(
            operationSelected.date,
            'DD-MM-YYYY, HH:mm:ss'
          )}`
        }}
      </FormattedText>
      <FormattedText
        v-if="hasTicketNumber"
        className="operation-name"
        type="text-subtitle-1"
      >
        {{
          `${getTranslatedText(
            'operationsView.detail.ticketNumber'
          )}: ${getTicketCodeFromDate(operationSelected.date)}`
        }}
      </FormattedText>
      <FormattedText type="text-subtitle-1" className="operation-name">
        {{ `${getTranslatedText('operationsView.detail.doneBy')} ${getUser}` }}
      </FormattedText>
      <v-chip
        v-if="hasPromotion || hasTicketAtCostPromotion"
        small
        color="error"
        label
        class="align-self-start mb-2 mt-1 text-body-2"
      >
        <v-icon small class="mr-1">mdi-sale</v-icon>
        {{ ticketPromotion }}
      </v-chip>
      <div class="d-flex align-center">
        <FormattedText
          className="font-weight-bold"
          type="text-h5"
          v-if="showTotal"
        >
          {{
            `${getTranslatedText(
              'operationsView.detail.totalAmount'
            )}: ${formatNumberFromDbToCurrency(operationSelected.amount)}`
          }}
        </FormattedText>
        <FormattedText
          v-if="hasPromotion"
          type="text-h6"
          color="grey"
          className="text-decoration-line-through ml-2 text--darken-1 font-weight-regular"
        >
          ({{ formatNumberFromDbToCurrency(amountWithoutDiscount) }})
        </FormattedText>
      </div>
      <FormattedText
        v-if="getPaid !== -1"
        type="text-subtitle-1"
        className="operation-name"
      >
        {{ `${getTranslatedText('operationsView.detail.paid')}: ${getPaid}` }}
      </FormattedText>
    </div>
    <div class="default-icon">
      <v-icon x-large color="white">{{ getIcon }}</v-icon>
    </div>
  </v-card-title>
</template>

<script>
import { mapState } from 'vuex'
import { isNil } from 'ramda'

import { idOperations } from '@/config/cashOperationsVariables'
import paymentMethods from '@/config/paymentMethods'
import { promotions } from '@/config/promotions'

import { getOperationText, getOperationIcon } from '@/tools/cashOperationsTools'
import { getTranslatedText } from '@/tools/data'
import { getDateWithFormat } from '@/tools/dates'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'
import { discountTypes, getPercentFromAmount } from '@/tools/promotions'
import { getTicketCodeFromDate, getTotalTicketPrice } from '@/tools/ticket'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'OperationDetailHeader',
  components: { FormattedText },
  computed: {
    ...mapState('operationsView', {
      operationSelected: state => state.operationDetailDialog.operationSelected,
    }),
    ...mapState('users', ['users']),
    ...mapState('salesView', ['paymentProvidersByType']),
    getOperationType() {
      const operationText = this.getTranslatedText(
        getOperationText(this.operationSelected.operationType)
      )
      let entityName = undefined
      switch (this.operationSelected.operationType) {
        case idOperations.ID_OPERATION_CASH_SALE:
        case idOperations.ID_OPERATION_CREDIT_SALE:
        case idOperations.ID_OPERATION_EXTERNAL_PAYMENT_SALE:
          if (isNil(this.operationSelected.details.customer)) break
          entityName = this.operationSelected.details.customer.name
          break
        case idOperations.ID_OPERATION_CASH_PURCHASE:
        case idOperations.ID_OPERATION_CREDIT_PURCHASE:
          entityName = this.operationSelected.details.vendor?.name
          break
        case idOperations.ID_OPERATION_EXPENSE:
          entityName = this.operationSelected.details.description
          break
      }
      return entityName === undefined
        ? operationText
        : this.$options.filters.truncate(`${operationText} a ${entityName}`, 35)
    },
    getExtraInfoOperationType() {
      if (
        this.operationSelected.operationType !==
        idOperations.ID_OPERATION_EXTERNAL_PAYMENT_SALE
      ) {
        return null
      }
      return this.getPaymentMethod(this.operationSelected.details)
    },
    showTotal() {
      return (
        this.operationSelected.operationType !==
        idOperations.ID_OPERATION_EXPENSE
      )
    },
    getUser() {
      if (this.operationSelected.userId === '')
        return this.getTranslatedText('operationsView.listView.unknownUser')
      return this.users.find(user => user._id == this.operationSelected.userId)
        .name
    },
    getIcon() {
      return getOperationIcon(this.operationSelected.operationType).icon
    },
    getPaid() {
      let debt = undefined
      switch (this.operationSelected.operationType) {
        case idOperations.ID_OPERATION_CASH_SALE:
        case idOperations.ID_OPERATION_CREDIT_SALE:
          debt = this.operationSelected.details.receivable
          break
        case idOperations.ID_OPERATION_CASH_PURCHASE:
        case idOperations.ID_OPERATION_CREDIT_PURCHASE:
          debt = this.operationSelected.details.payable
          break
      }
      if (debt === undefined) return -1
      return formatNumberFromDbToCurrency(debt.settled)
    },
    hasPromotion() {
      return this.operationSelected.details.promotion > 0
    },
    hasTicketAtCostPromotion() {
      return (
        this.operationSelected.details.items?.some(
          item => item.promotion_type_id === promotions.SALE_TICKET_AT_COST
        ) || false
      )
    },
    amountWithoutDiscount() {
      if (this.hasTicketAtCostPromotion) {
        return getTotalTicketPrice(
          this.operationSelected.details.items,
          'unit_price',
          'sales_quantity'
        )
      }
      return (
        this.operationSelected.amount + this.operationSelected.details.promotion
      )
    },
    ticketPromotion() {
      if (this.hasTicketAtCostPromotion) {
        return this.getTranslatedText('operationsView.detail.saleAtCost')
      }
      let promotion = formatNumberFromDbToCurrency(
        this.operationSelected.details.promotion
      )
      if (
        discountTypes.isDiscountPerPercent(
          this.operationSelected.details.promotion_type
        )
      ) {
        promotion = `${getPercentFromAmount(
          this.operationSelected.details.promotion,
          this.amountWithoutDiscount
        )}% (${promotion})`
      }
      return this.getTranslatedText(
        `operationsView.detail.${this.operationSelected.details.promotion_type}Discount`,
        promotion
      )
    },
    hasTicketNumber() {
      return [
        idOperations.ID_OPERATION_CASH_SALE,
        idOperations.ID_OPERATION_CREDIT_SALE,
        idOperations.ID_OPERATION_EXTERNAL_PAYMENT_SALE,
        idOperations.ID_OPERATION_OWNER_SALE,
        idOperations.ID_OPERATION_CASH_PURCHASE,
        idOperations.ID_OPERATION_CREDIT_PURCHASE,
      ].includes(this.operationSelected.operationType)
    },
  },
  methods: {
    getTicketCodeFromDate,
    getTranslatedText,
    getDateWithFormat,
    formatNumberFromDbToCurrency,
    getPaymentMethod(operationDetails) {
      const { payment_method, payment_method_provider } = operationDetails
      const paymentMethod = paymentMethods.getPaymentMethodKeyFromId(
        payment_method
      )
      let paymentTypeText = ''
      if (paymentMethods.defaultPaymentMethods.includes(paymentMethod)) {
        paymentTypeText = `${this.getTranslatedText(
          `operationsView.operationType.${paymentMethod}`
        )}:`
      }
      if (!this.paymentProvidersByType[paymentMethod]) return paymentTypeText
      const provider = this.paymentProvidersByType[paymentMethod].find(
        item => item.id === payment_method_provider
      )
      if (!provider) return paymentTypeText
      const commissionsText =
        paymentMethods.isCardSale(paymentMethod) && provider.commissions > 0
          ? `(${this.getTranslatedText(
              'operationsView.operationType.commissions'
            )} ${provider.commissions}%)`
          : ''
      return `${paymentTypeText} ${provider.label} ${commissionsText}`
    },
  },
}
</script>
