import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

const setConfig = (state, methods) => ({
  state,
  methods,
  columns: [
    {
      id: 'right',
      class: 'd-flex flex-column ml-4 right-column',
      rows: [
        {
          id: 'nameRow',
          class: 'd-flex',
          elements: [
            {
              id: 'productName',
              componentType: 'text',
              type: 'text-h6',
              class: 'pl-1',
              color: 'productProductNameTicket',
              value: state.returnProduct.name,
              shorter: state.truncateLength,
            },
            {
              id: 'totalPrice',
              componentType: 'text',
              type: 'text-h5',
              class: 'ml-auto pr-1',
              className: 'font-weight-bold',
              color: 'productProductNameTicket',
              value: formatNumberFromDbToCurrency(
                -state.returnProduct.amountToDiscount
              ),
            },
          ],
        },
        {
          id: 'detailsRow',
          class: 'd-flex',
          elements: [
            {
              id: 'discountLabel',
              componentType: 'text',
              type: 'text-subtitle-1',
              class: 'pl-1',
              className: 'font-weight-bold',
              color: 'productCardWarningPrimary',
              value: methods.getTranslatedText(
                'purchaseView.returnProductType.discount'
              ),
            },
            {
              id: 'quantity',
              componentType: 'text',
              class: 'pl-4',
              type: 'text-subtitle-1',
              className: 'font-weight-bold',
              color: 'productProductNameTicket',
              value: `${state.returnProduct.quantity} ${
                state.returnProduct.isGramaje ? 'gr' : 'pzs'
              }`,
            },
            {
              id: 'unitCost',
              componentType: 'text',
              class: 'pl-4',
              type: 'text-subtitle-1',
              className: 'font-weight-bold',
              color: 'productProductNameTicket',
              value: formatNumberFromDbToCurrency(state.returnProduct.price),
            },
          ],
        },
      ],
    },
  ],
})

export default setConfig
