import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

const setConfig = (state, methods) => ({
  state,
  methods,
  singleWidgets: {
    firstSection: [
      {
        id: 'customer',
        type: 'SingleDataWidget',
        value: state.debt.customer.name,
        label: 'salesView.ticket.client',
        labelIcon: 'mdi-account',
        iconColor: 'operationsSecondary',
      },
    ],
    secondSection: [
      {
        id: 'debt',
        type: 'SingleDataWidget',
        value: formatNumberFromDbToCurrency(state.debt.customer.debt),
        label: 'customersView.customerDetails.debt',
        labelIcon: 'mdi-chart-bar',
        iconColor: 'operationsSecondary',
        reverse: true,
      },
    ],
  },
})

export default setConfig
