<template>
  <div>
    <v-card-actions>
      <div>
        <v-btn
          v-if="showDeleteButton"
          color="error"
          ref="operationDetailDeleteButton"
          @click="openDeleteOperationDialog"
          v-track:click="{
            category: $route.name,
            screen: 'OperationDetails',
            name: 'Show confirm delete operation',
          }"
        >
          <v-icon color="white">mdi-delete-outline</v-icon>
          <FormattedText
            intl
            value="productsView.details.delete"
            color="white"
          />
        </v-btn>
        <DeleteOperationDialog v-if="deleteOperationDialog.isOpen" />
        <v-btn
          v-if="showPayDebtButton"
          color="secondary"
          ref="customerDetailPayDebtButton"
          @click="openSettleDebtDialog"
          v-track:click="{
            category: $route.name,
            screen: 'OperationDetails',
            name: 'Show confirm pay debt',
          }"
        >
          <v-icon color="white">mdi-cash-refund</v-icon>
          <FormattedText
            intl
            value="customersView.customerDetails.payDebt"
            color="white"
          />
        </v-btn>
        <v-btn
          color="primary"
          ref="repeatPurchaseButton"
          v-if="showRepeatPurchase"
          @click="openRepeatPurchaseDialog"
          v-track:click="{
            category: $route.name,
            screen: 'OperationDetails',
            name: 'Show confirm repeat purchase',
          }"
        >
          <v-icon color="white">mdi-refresh</v-icon>
          <FormattedText
            intl
            value="vendorsView.dialogs.detail.lastOrders.repeatOrder"
            color="white"
          />
        </v-btn>
      </div>
      <div class="text-right">
        <v-btn
          color="accent"
          ref="operationDetailCloseButton"
          @click="onClickClose"
          v-track:click="{
            category: $route.name,
            screen: 'OperationDetails',
            name: 'Close operation details',
          }"
        >
          <v-icon>mdi-close-circle-outline</v-icon>
          <FormattedText
            intl
            value="productsView.details.close"
            color="white"
          />
        </v-btn>
      </div>
    </v-card-actions>
    <SettleCreditSaleDialog
      v-if="settleCreditSaleDialog.isOpen"
      :customer="this.operationSelected.details.customer"
    />
    <SettleCreditPurchaseDialog
      v-if="settleCreditPurchaseDialog.isOpen"
      :vendor="this.operationSelected.details.vendor"
    />
  </div>
</template>

<script>
import { mapState, mapActions } from 'vuex'
import { isNil } from 'ramda'

import { operationsLimit } from '@/config/env'
import { idOperations } from '@/config/cashOperationsVariables'
import CASH_OPERATIONS_EVENTS from '@/config/events/databaseAPI/cashOperationsEvents'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import operationsViewActions from '@/store/operationsView/actions.types'
import customersViewActions from '@/store/customersView/actions.types'
import vendorsViewActions from '@/store/vendorsView/actions.types'

import FormattedText from '@/components/shared/FormattedText'
import DeleteOperationDialog from '@/components/OperationsView/OperationDetail/Footer/DeleteOperationDialog'
import SettleCreditSaleDialog from '@/components/CustomersView/CustomerDetail/CreditSalesTab/SettleCreditSaleDialog'
import SettleCreditPurchaseDialog from '@/components/VendorsView/VendorDetailDialog/LastOrdersTab/SettleCreditPurchaseDialog'

const OPS_CANNOT_DELETED = [
  idOperations.ID_OPERATION_OWNER_SALE,
  idOperations.ID_OPERATION_EXTERNAL_PAYMENT_SALE,
  idOperations.ID_OPERATION_ADDCASH,
  idOperations.ID_OPERATION_TAKECASH,
]
const OPS_SALE_CAN_DELETED = [
  idOperations.ID_OPERATION_CASH_SALE,
  idOperations.ID_OPERATION_CREDIT_SALE,
]

const OPS_PURCHASE_CAN_DELETED = [
  idOperations.ID_OPERATION_CASH_PURCHASE,
  idOperations.ID_OPERATION_CREDIT_PURCHASE,
]

export default {
  name: 'OperationDetailFooter',
  components: {
    FormattedText,
    DeleteOperationDialog,
    SettleCreditSaleDialog,
    SettleCreditPurchaseDialog,
  },
  computed: {
    ...mapState('operationsView', {
      operationSelected: state => state.operationDetailDialog.operationSelected,
      deleteOperationDialog: state => state.deleteOperationDialog,
    }),
    ...mapState('customersView', ['settleCreditSaleDialog']),
    ...mapState('vendorsView', [
      'settleCreditPurchaseDialog',
      'repeatPurchaseConfirmDialog',
    ]),
    ...mapState('usersView', {
      user: state => state.selectedUser,
    }),
    showDeleteButton() {
      const { operationType } = this.operationSelected
      if (
        this.userCannotDeleteSalePurchaseOps(operationType) ||
        this.userCannotDeleteExpensesOps(operationType)
      ) {
        return false
      }
      return !OPS_CANNOT_DELETED.includes(operationType)
    },
    showPayDebtButton() {
      if (!this.operationSelected.details) return false
      const debt =
        this.operationSelected.operationType ===
        idOperations.ID_OPERATION_CREDIT_SALE
          ? this.operationSelected.details.receivable
          : this.operationSelected.details.payable
      if (debt === undefined) return false
      return debt.amount > debt.settled
    },
    showRepeatPurchase() {
      return (
        [
          idOperations.ID_OPERATION_CASH_PURCHASE,
          idOperations.ID_OPERATION_CREDIT_PURCHASE,
        ].includes(this.operationSelected.operationType) &&
        !isNil(this.operationSelected.details.vendor)
      )
    },
  },
  methods: {
    ...mapActions('operationsView', [
      operationsViewActions.setOperationDetailDialogStatus,
      operationsViewActions.setDeleteOperationDialogStatus,
    ]),
    ...mapActions('customersView', [
      customersViewActions.setSettleCreditSaleDialogStatus,
      customersViewActions.setCustomerDetailDialogStatus,
    ]),
    ...mapActions('vendorsView', [
      vendorsViewActions.setSettleCreditPurchaseDialogStatus,
      vendorsViewActions.toggleRepeatPurchaseConfirmDialog,
      vendorsViewActions.setSelectedVendor,
    ]),
    userCannotDeleteSalePurchaseOps(operationType) {
      return (
        (OPS_SALE_CAN_DELETED.includes(operationType) ||
          OPS_PURCHASE_CAN_DELETED.includes(operationType)) &&
        this.user.salesPurchasesReturnPermission === 1
      )
    },
    userCannotDeleteExpensesOps(operationType) {
      return (
        operationType === idOperations.ID_OPERATION_EXPENSE &&
        this.user.expensesPermission === 1
      )
    },
    onClickClose() {
      this[operationsViewActions.setOperationDetailDialogStatus]({
        isOpen: false,
      })
    },
    openDeleteOperationDialog() {
      rendererEventsService.send(CASH_OPERATIONS_EVENTS.channel, {
        event: CASH_OPERATIONS_EVENTS.events.operationCanBeUndone.name,
        data: { operationSelected: this.operationSelected },
      })
    },
    openSettleDebtDialog() {
      this.operationSelected.operationType ===
      idOperations.ID_OPERATION_CREDIT_SALE
        ? this[customersViewActions.setSettleCreditSaleDialogStatus]({
            isOpen: true,
            sale: this.operationSelected.details,
          })
        : this[vendorsViewActions.setSettleCreditPurchaseDialogStatus]({
            isOpen: true,
            purchase: this.operationSelected.details,
          })
    },
    openRepeatPurchaseDialog() {
      this[vendorsViewActions.setSelectedVendor](
        this.operationSelected.details.vendor
      )
      this[vendorsViewActions.toggleRepeatPurchaseConfirmDialog](
        this.operationSelected.details
      )
    },
    cashOperationsListener(event, payload) {
      const replies = {
        [CASH_OPERATIONS_EVENTS.events.operationCanBeUndone.replies
          .success]: () => {
          payload.data.canBeUndone
            ? this[operationsViewActions.setDeleteOperationDialogStatus](true)
            : notificationsService.showError(
                'notification.operations.operationCantBeUndone',
                this.$vuetify.lang
              )
        },

        [CASH_OPERATIONS_EVENTS.events.operationCanBeUndone.replies
          .error]: () => {
          notificationsService.showError(
            'notification.operations.operationCantBeUndone',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    rendererEventsService.subscribe(
      CASH_OPERATIONS_EVENTS.replyChannel,
      this.cashOperationsListener
    )
  },
  mounted() {
    this.$root.$on(
      ['debtSettled', 'operationDeleted', 'productDeleted', 'saleComboDeleted'],
      () => {
        rendererEventsService.send(CASH_OPERATIONS_EVENTS.channel, {
          event: CASH_OPERATIONS_EVENTS.events.getLastNOperations.name,
          data: operationsLimit,
        })
        this.onClickClose()
      }
    )
  },
  beforeDestroy() {
    this.$root.$off([
      'debtSettled',
      'operationDeleted',
      'productDeleted',
      'saleComboDeleted',
    ])
    rendererEventsService.removeListener(
      CASH_OPERATIONS_EVENTS.replyChannel,
      this.cashOperationsListener
    )
  },
}
</script>
