<template>
  <div>
    <ComboPromotion
      :promotion="combo"
      :ticket-index="0"
      :hide-delete-btn="hideDeleteBtn"
      @deleteComboFromSaleOp="openDeleteComboDialog"
    />
    <DeleteComboDialog
      v-if="showDeleteComboDialog"
      :showDialog.sync="showDeleteComboDialog"
      :combo="combo"
      :operation="operation"
    />
  </div>
</template>

<script>
import { mapActions } from 'vuex'

import CASH_OPERATIONS_EVENTS from '@/config/events/databaseAPI/cashOperationsEvents'

import { comboPromotion } from '@/tools/customPromotions'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import operationsViewActions from '@/store/operationsView/actions.types'

import ComboPromotion from '@/components/shared/Ticket/ComboPromotion'
import DeleteComboDialog from '@/components/OperationsView/OperationDetail/ExtraDetails/DetailCombo/DeleteComboDialog'

export default {
  name: 'DetailCombo',
  components: { DeleteComboDialog, ComboPromotion },
  props: {
    combo: {
      type: Object,
      required: true,
    },
    operation: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      showDeleteComboDialog: false,
    }
  },
  computed: {
    hideDeleteBtn() {
      return (
        this.isThereComboWithAnyProducts(
          this.operation.details.promotions,
          this.combo
        ) ||
        this.isThereAnyCoincidenceWithProducts(
          this.operation.details.items,
          this.combo
        )
      )
    },
  },
  methods: {
    ...mapActions('operationsView', [
      operationsViewActions.setDeleteOperationDialogStatus,
    ]),
    isThereComboWithAnyProducts(saleCombos, combo) {
      return saleCombos.some(promo => {
        if (promo.id === combo.id) return false
        return comboPromotion
          .getProductsKey()
          .some(
            key =>
              promo.promotions[`${key}Id`] ===
                combo.promotions.firstProductId ||
              promo.promotions[`${key}Id`] === combo.promotions.secondProductId
          )
      })
    },
    isThereAnyCoincidenceWithProducts(saleItems, combo) {
      return saleItems.some(item =>
        comboPromotion
          .getProductsKey()
          .some(key => item.product_id === combo.promotions[`${key}Id`])
      )
    },
    openDeleteComboDialog() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'OperationComboDetails',
        name: 'Remove combo',
      })
      rendererEventsService.send(CASH_OPERATIONS_EVENTS.channel, {
        event: CASH_OPERATIONS_EVENTS.events.operationCanBeUndone.name,
        data: { operationSelected: this.operation, combo: this.combo },
      })
    },
    canDeleteComboListener(event, payload) {
      const events = CASH_OPERATIONS_EVENTS.events
      const replies = {
        [`${events.operationCanBeUndone.replies.success}-combo${this.combo.saleComboId}`]: () => {
          if (!payload.data.canBeUndone) {
            this.$track({
              type: 'system',
              action: 'can_be_undone',
              category: this.$route.name,
              screen: 'OperationComboDetails',
              name: 'Combo cannot be deleted',
            })
            this.showComboCantBeUndoneNotification()
            return
          }
          if (this.saleHasMoreThanOneItem()) {
            this.$track({
              type: 'system',
              action: 'can_be_undone',
              category: this.$route.name,
              screen: 'OperationComboDetails',
              name: 'Show confirm delete combo',
            })
            this.showDeleteComboDialog = true
            return
          }
          this.$track({
            type: 'system',
            action: 'can_be_undone',
            category: this.$route.name,
            screen: 'OperationComboDetails',
            name: 'Show confirm delete operation',
          })
          this[operationsViewActions.setDeleteOperationDialogStatus](true)
        },
        [`${events.operationCanBeUndone.replies.error}-combo${this.combo.saleComboId}`]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: this.$route.name,
            screen: 'OperationComboDetails',
            name: 'Error checking if combo can be deleted',
          })
          this.showComboCantBeUndoneNotification()
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    saleHasMoreThanOneItem() {
      return (
        this.operation.details.items.length +
          this.operation.details.promotions.length >
        1
      )
    },
    showComboCantBeUndoneNotification() {
      notificationsService.showError(
        'notification.operations.comboCantBeUndone',
        this.$vuetify.lang
      )
    },
  },
  created() {
    rendererEventsService.subscribe(
      CASH_OPERATIONS_EVENTS.replyChannel,
      this.canDeleteComboListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      CASH_OPERATIONS_EVENTS.replyChannel,
      this.canDeleteComboListener
    )
  },
}
</script>
