<template>
  <v-card flat class="py-2 px-4 d-flex return-card">
    <v-icon large color="productCardWarningPrimary" class="align-self-start">
      $vuetify.icons.values.returnProduct
    </v-icon>
    <DiscountProductType
      v-if="isDiscountType"
      style="width:100%"
      class="pr-4"
      :config="productConfig"
    />
    <ChangeProductType
      v-else
      style="width:100%"
      class="pr-4"
      :config="productConfig"
    />
  </v-card>
</template>

<script>
import { mapState } from 'vuex'

import { returnTypes } from '@/config/returnProductTypes'

import { getTranslatedText } from '@/tools/data'

import setDiscountProductConfig from '@/components/OperationsView/OperationDetail/ExtraDetails/DetailReturnItem/discountProductConfig'
import setChangeProductConfig from '@/components/OperationsView/OperationDetail/ExtraDetails/DetailReturnItem/changeProductConfig'
import DiscountProductType from '@/components/shared/ChangeProductType'
import ChangeProductType from '@/components/shared/ChangeProductType'

export default {
  name: 'DetailReturnItem',
  components: { DiscountProductType, ChangeProductType },
  props: {
    item: {
      type: Object,
      required: true,
    },
  },
  computed: {
    ...mapState('app', ['windowSize', 'sidebarOpened']),
    productConfig() {
      return this.isDiscountType
        ? setDiscountProductConfig(
            {
              returnProduct: this.item,
              truncateLength: this.truncateLength,
              lang: this.$vuetify.lang,
            },
            {
              getTranslatedText: this.getTranslatedText,
            }
          )
        : setChangeProductConfig(
            {
              returnProduct: this.item,
              truncateLength: this.truncateLength,
              lang: this.$vuetify.lang,
            },
            {
              getTranslatedText: this.getTranslatedText,
            }
          )
    },
    isDiscountType() {
      return this.item.returnType === returnTypes.DISCOUNT
    },
    truncateLength() {
      const value = this.sidebarOpened
        ? this.windowSize.x - 256 + 250 * this.ticketCols
        : this.windowSize.x - 56 + 250 * this.ticketCols
      if (value < 2350) return '14'
      if (value < 2450) return '16'
      if (value < 2525) return '18'
      if (value < 2600) return '20'
      if (value < 2692) return '22'
      if (value < 2785) return '24'
      if (value < 2850) return '26'
      if (value < 2900) return '28'
      if (value < 3000) return '30'
      if (value < 3100) return '33'
      if (value < 3250) return '36'
      return '40'
    },
  },
  methods: {
    getTranslatedText,
  },
}
</script>

<style lang="scss" scoped>
.return-card {
  background-color: var(--v-cardBackgroundSecondary-base);
  border-radius: 10px;
  border-left: 6px solid var(--v-productCardWarningPrimary-base);
  margin-top: 10px;
}
</style>
