import { idOperations } from '@/config/cashOperationsVariables'
import {
  purchaseItems as purchaseItemsMapper,
  saleItems as saleItemsMapper,
} from '@/config/storeMapper'

import { returnTypes } from '@/config/returnProductTypes'

import { mapStoreObject } from '@/tools/data'
import salesTools from '@/tools/sales'
import { applyTax } from '@/tools/purchases/tools'

const SALES_OPERATIONS = [
  idOperations.ID_OPERATION_CASH_SALE,
  idOperations.ID_OPERATION_CREDIT_SALE,
  idOperations.ID_OPERATION_EXTERNAL_PAYMENT_SALE,
]

const PURCHASE_OPERATIONS = [
  idOperations.ID_OPERATION_CASH_PURCHASE,
  idOperations.ID_OPERATION_CREDIT_PURCHASE,
]

const getProductsByOperationType = function() {
  const { operationType } = this.operationSelected
  if (SALES_OPERATIONS.includes(operationType)) {
    return getProductsForSale(
      this.operationSelected.details.items,
      this.storeInventoryProducts,
      this.operationSelected.operationType
    )
  }
  if (idOperations.ID_OPERATION_OWNER_SALE === operationType) {
    return getProductsForOwnerSale(
      this.operationSelected.details.items,
      this.storeInventoryProducts
    )
  }
  if (PURCHASE_OPERATIONS.includes(operationType)) {
    return getProductsForPurchase(
      this.operationSelected.details.items,
      this.storeInventoryProducts
    )
  }
  return []
}

const getProductsForSale = (items, products, payOption) => {
  return items.reduce((result, item) => {
    if (item.product_id === -1 && item.name === 'commission') return result
    const productFound = products.find(
      product => product.id === item.product_id
    )
    const itemMapper = mapStoreObject(item, saleItemsMapper)
    itemMapper.promotions = item.promotions
    itemMapper.price = salesTools.getProductPrice(
      {
        payOption,
      },
      {
        ...productFound,
        ...itemMapper,
        unitPrice: itemMapper.priceWithoutPromotion,
      }
    )
    result.push({
      ...itemMapper,
      description: productFound?.alternativeName || '',
      name: itemMapper.name !== '' ? itemMapper.name : productFound.name,
    })
    return result
  }, [])
}

const getProductsForOwnerSale = (items, products) => {
  return items.reduce((result, item) => {
    if (item.product_id === -1 && item.name === 'commission') return result
    const productFound = products.find(
      product => product.id === item.product_id
    )
    result.push({
      ...mapStoreObject(item, saleItemsMapper),
      isGeneric: !productFound && item.price_from === 1 ? 1 : 0,
      description: productFound?.alternativeName || '',
      price: item.price_cost,
    })
    return result
  }, [])
}

const getProductsForPurchase = (items, products) => {
  return items.reduce((result, item) => {
    if (item.product_id === -1 && item.name === 'commission') return result
    const productFound = products.find(
      product => product.id === item.product_id
    )
    result.push({
      ...mapStoreObject(item, purchaseItemsMapper),
      description: productFound?.alternativeName || '',
      costWithoutPromotion: item.unit_cost * applyTax(productFound?.iva || 0),
    })
    return result
  }, [])
}

const getReturnProducts = function() {
  if (!PURCHASE_OPERATIONS.includes(this.operationSelected.operationType)) {
    return []
  }
  return this.operationSelected.details.returnItems.map(item => {
    const ticketReturn = {
      id: item.product_return_id,
      name: item.product_return_name,
      quantity: item.product_return_quantity,
      price: item.product_return_cost,
      returnType: item.return_type,
      isGramaje: item.product_return_is_gramaje,
    }
    if (item.return_type === returnTypes.DISCOUNT) {
      return {
        ...ticketReturn,
        amountToDiscount: item.amount_to_discount,
      }
    }
    return {
      ...ticketReturn,
      isGramajeChange: item.product_change_is_gramaje,
      idChange: item.product_change_id,
      nameChange: item.product_change_name,
      quantityChange: item.product_change_quantity,
      priceChange: item.product_change_cost,
    }
  })
}

const getSaleCombos = function() {
  if (!SALES_OPERATIONS.includes(this.operationSelected.operationType)) {
    return []
  }
  return this.operationSelected.details.promotions.map(promo => {
    return {
      ...promo,
      promotions: {
        ...promo.promotions,
        firstProduct: this.storeInventoryProducts.find(
          product => product.id === promo.promotions.firstProductId
        ),
        secondProduct: this.storeInventoryProducts.find(
          product => product.id === promo.promotions.secondProductId
        ),
      },
    }
  })
}

export default {
  getProductsByOperationType,
  getReturnProducts,
  getSaleCombos,
}
