import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'
import { formatDate } from '@/tools/dates'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-alert-circle',
    title: 'operationsView.deleteOperationDialog.title',
    titleBackground: '',
    titleColor: 'textPrimary',
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    messages: ['operationsView.deleteOperationDialog.message'],
    extraValuesMessages: [
      formatNumberFromDbToCurrency(state.operation.amount),
      formatDate(state.operation.date),
    ],
    height: 225,
    maxWidth: 500,
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: state.routeName,
        screen: 'DeleteOperationDialog',
        name: 'Cancel',
      })
      methods.closeDialog()
    },
    onClickAccept: () => methods.undoOperation(),
  },
})

export default setConfig
