<template>
  <div>
    <v-tooltip
      v-for="(button, index) in config"
      :key="`multiple-button-${index}`"
      bottom
      :disabled="!button.tooltip"
    >
      <template #activator="{ on, attrs }">
        <v-btn
          v-on="on"
          v-bind="attrs"
          :ref="button.ref"
          :color="button.color"
          class="action-button"
          :class="{ 'mr-4': index < config.length - 1, ...button.class }"
          @click="button.onClick"
        >
          <FormattedText intl :value="button.text" color="white" />
        </v-btn>
      </template>
      <span v-if="button.tooltip">
        {{ getTranslatedText(button.tooltip.text) }}
      </span>
    </v-tooltip>
  </div>
</template>

<script>
import { getTranslatedText } from '@/tools/data'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'MultipleButtons',
  components: { FormattedText },
  props: {
    config: {
      type: Array,
      required: true,
    },
  },
  methods: { getTranslatedText },
}
</script>

<style scoped lang="scss">
.action-button {
  border-radius: 10px;
}
</style>
