const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-alert-circle',
    title: 'operationsView.deleteProductDialog.title',
    titleBackground: '',
    titleColor: 'textPrimary',
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    messages: ['operationsView.deleteProductDialog.message'],
    extraValuesMessages: [state.product.product_name],
    height: 225,
    maxWidth: 500,
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: state.routeName,
        screen: 'DeleteProductDialog',
        name: 'Cancel',
      })
      methods.closeDialog()
    },
    onClickAccept: () => methods.deleteProduct(),
  },
})

export default setConfig
