<template>
  <div>
    <DialogCard :config="componentConfig.dialogData">
      <template v-slot:footer>
        <MultipleButtons :config="componentConfig.multipleButtons" />
      </template>
    </DialogCard>
    <ExternalCashRegisterInfo @userHasBeenInformed="settleDebt(true)" />
  </div>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { testMode } from '@/config/env'

import VENDORS_DB_API_EVENTS from '@/config/events/databaseAPI/vendorsEvents'

import { formatNumberFromDb, formatNumberToDb } from '@/tools/numbersFormat'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import appActions from '@/store/app/actions.types'
import vendorsViewActions from '@/store/vendorsView/actions.types'
import vendorsActions from '@/store/vendors/actions.types'
import usersViewActions from '@/store/usersView/actions.types'

import DialogCard from '@/components/shared/DialogCard'
import setConfig from '@/components/VendorsView/VendorDetailDialog/LastOrdersTab/SettleCreditPurchaseDialog/config'
import MultipleButtons from '@/components/shared/MultipleButtons'
import ExternalCashRegisterInfo from '@/components/shared/ExternalCashRegisterInfo'

export default {
  name: 'SettleCreditPurchaseDialog',
  components: { ExternalCashRegisterInfo, MultipleButtons, DialogCard },
  props: {
    vendor: {
      type: Object,
      default: null,
    },
  },
  data() {
    return {
      finishDebtPurchase: false,
    }
  },
  computed: {
    ...mapState('usersView', ['selectedUser', 'estimatedCash']),
    ...mapState('vendorsView', [
      'settleCreditPurchaseDialog',
      'selectedVendor',
    ]),
    componentConfig() {
      return setConfig(
        {
          isOpen: this.settleCreditPurchaseDialog.isOpen,
          purchase: this.settleCreditPurchaseDialog.purchase,
          routeName: this.$route.name,
        },
        {
          closeDialog: this.closeDialog,
          showInfoDialog: this.showInfoDialog,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [
      appActions.addPendingSyncOperation,
      appActions.toggleExternalCashRegisterInfoDialog,
    ]),
    ...mapActions('vendors', [vendorsActions.settleCreditPurchase]),
    ...mapActions('vendorsView', [
      vendorsViewActions.setSettleCreditPurchaseDialogStatus,
      vendorsViewActions.toggleVendorDetailDialog,
    ]),
    ...mapActions('usersView', [usersViewActions.setUserEstimatedCash]),
    closeDialog() {
      this[vendorsViewActions.setSettleCreditPurchaseDialogStatus]({
        isOpen: false,
        purchase: null,
      })
    },
    showInfoDialog(isFromExternalCashRegister = false) {
      if (this.finishDebtPurchase === true) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'SettleCreditPurchaseDialog',
        name: `Pay debt with ${
          isFromExternalCashRegister ? 'external cash' : 'cash register'
        }`,
      })
      if (!isFromExternalCashRegister) {
        this.settleDebt(isFromExternalCashRegister)
        return
      }
      this[appActions.toggleExternalCashRegisterInfoDialog](true)
    },
    settleDebt(isFromExternalCashRegister) {
      this.finishDebtPurchase = true
      rendererEventsService.send(VENDORS_DB_API_EVENTS.channel, {
        event: VENDORS_DB_API_EVENTS.events.settleCreditPurchase.name,
        data: {
          purchase: this.settleCreditPurchaseDialog.purchase,
          vendor: this.vendor === null ? this.selectedVendor : this.vendor,
          user: this.selectedUser.id,
          estimatedCash: this.getEstimatedCash(),
          isFromExternalCashRegister,
        },
      })
    },
    getEstimatedCash() {
      const stateEstimatedCash =
        this.estimatedCash === null || this.estimatedCash === undefined
          ? 0
          : this.estimatedCash
      return formatNumberToDb(stateEstimatedCash)
    },
    onPurchaseSettled(data) {
      this.$track({
        type: 'system',
        action: 'settle_debt',
        category: this.$route.name,
        screen: 'SettleCreditPurchaseDialog',
        name: 'Close dialog',
      })
      this[appActions.addPendingSyncOperation]()
      this[vendorsActions.settleCreditPurchase](data.vendor)
      this[usersViewActions.setUserEstimatedCash](
        formatNumberFromDb(data.estimatedCash)
      )
      this.finishDebtPurchase = false
      notificationsService.showSuccess(
        'vendorsView.dialogs.settleDebtDialog.idividualDebtSettled',
        this.$vuetify.lang,
        { timeout: 8000 }
      )
      this.closeDialog()
      this[vendorsViewActions.toggleVendorDetailDialog]()
      this.$root.$emit('debtSettled')
    },
    vendorsCreditsListener(event, payload) {
      const settleCreditPurchaseReplies =
        VENDORS_DB_API_EVENTS.events.settleCreditPurchase.replies
      const replies = {
        [settleCreditPurchaseReplies.success]: () =>
          this.onPurchaseSettled(payload.data),
        [settleCreditPurchaseReplies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: this.$route.name,
            screen: 'SettleCreditPurchaseDialog',
            name: 'Error settling purchase debt',
          })
          this.finishDebtPurchase = false
          notificationsService.showError(
            'vendorsView.dialogs.settleDebtDialog.errorSettlingDebt',
            this.$vuetify.lang,
            { timeout: 8000 }
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  mounted() {
    if (testMode) return
    rendererEventsService.subscribe(
      VENDORS_DB_API_EVENTS.replyChannel,
      this.vendorsCreditsListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      VENDORS_DB_API_EVENTS.replyChannel,
      this.vendorsCreditsListener
    )
  },
}
</script>
