<template>
  <v-dialog
    v-model="showDialog"
    content-class="default-dialog"
    :max-width="600"
    :overlay-opacity="0.15"
    persistent
  >
    <v-card>
      <v-card-title class="simple-title">
        <v-icon>mdi-information</v-icon>
        <FormattedText
          type="text-h6"
          intl
          value="externalCashInfo.title"
          class="title-text"
        />
      </v-card-title>
      <v-card-text>
        <p class="body-text">
          {{ getTranslatedText('externalCashInfo.info') }}
        </p>
        <p class="body-text">
          {{ getTranslatedText('externalCashInfo.estimatedCash') }}
        </p>
        <v-checkbox
          v-model="notShowAgain"
          hide-details
          :label="getTranslatedText('shared.notShowMsgAgain')"
        />
      </v-card-text>
      <v-card-actions>
        <v-spacer />
        <v-btn color="accent" ref="infoCancel" @click="hideDialog">
          {{ getTranslatedText('shared.cancel') }}
        </v-btn>
        <v-btn color="primary" ref="infoAccept" @click="infoAccepted">
          {{ getTranslatedText('shared.accept') }}
        </v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>
<script>
import { mapActions, mapState } from 'vuex'

import USER_EVENTS from '@/config/events/databaseAPI/usersEvents'

import { getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'
import usersViewActions from '@/store/usersView/actions.types'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'ExternalCashRegisterInfo',
  components: { FormattedText },
  data() {
    return {
      notShowAgain: false,
      showDialog: false,
    }
  },
  computed: {
    ...mapState('app', {
      isOpen: state => state.externalCashRegisterInfoDialog.isOpen,
    }),
    ...mapState('usersView', ['selectedUser']),
  },
  methods: {
    getTranslatedText,
    ...mapActions('app', [appActions.toggleExternalCashRegisterInfoDialog]),
    ...mapActions('usersView', [usersViewActions.setSelectedUser]),
    infoAccepted() {
      if (this.notShowAgain) {
        this.disabledShowInfo()
      }
      this.$emit('userHasBeenInformed')
      this.hideDialog()
    },
    disabledShowInfo() {
      rendererEventsService.send(USER_EVENTS.channel, {
        event: USER_EVENTS.events.update.name,
        data: {
          userId: this.selectedUser.id,
          values: { external_cash_info_disabled: 1 },
        },
      })
      this[usersViewActions.setSelectedUser]({
        ...this.selectedUser,
        externalCashInfoDisabled: 1,
      })
    },
    hideDialog() {
      this[appActions.toggleExternalCashRegisterInfoDialog](false)
    },
  },
  watch: {
    isOpen(newValue) {
      if (newValue && this.selectedUser.externalCashInfoDisabled === 1) {
        this.$emit('userHasBeenInformed')
        this.hideDialog()
        return
      }
      this.showDialog = newValue
    },
  },
}
</script>

<style scoped lang="scss">
.body-text {
  font-family: Lato, Helvetica, Roboto, Arial, sans-serif;
  line-height: 24px;
  font-size: 16px;
  word-break: break-word;
}
</style>
